function straightHair(head,color){
  // One continuous sheet of straight hair wraps the back of the head and falls to the upper back.
  const positions=[],indices=[],columns=isMobile?14:18,rows=isMobile?6:8;
  for(let row=0;row<=rows;row++){
    const t=row/rows;
    for(let col=0;col<=columns;col++){
      const angle=-Math.PI/2+Math.PI*col/columns;
      const width=.39*(1-.035*t);
      positions.push(Math.sin(angle)*width,.26-1.13*t+.025*t*t*Math.cos(angle),-.085-(.29+.025*t)*Math.cos(angle));
    }
  }
  for(let row=0;row<rows;row++)for(let col=0;col<columns;col++){
    const a=row*(columns+1)+col,b=a+columns+1;indices.push(a,b,a+1,b,b+1,a+1);
  }
  const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));geometry.setIndex(indices);geometry.computeVertexNormals();
  const hairMat=tinted(furMat,color);hairMat.side=T.DoubleSide;head.add(new T.Mesh(geometry,hairMat));
}

