const RANK_KEY='lucjusz-ranking',RANK_MAX=15;
function loadRanking(){try{const list=JSON.parse(localStorage.getItem(RANK_KEY)||'[]');return Array.isArray(list)?list:[];}catch{return[];}}
function saveRanking(list){list.sort((a,b)=>(b.at||0)-(a.at||0));localStorage.setItem(RANK_KEY,JSON.stringify(list.slice(0,RANK_MAX)));bestScore=list.reduce((m,e)=>Math.max(m,e.score||0),0);localStorage.setItem('lucjusz-best',String(bestScore));}
function submitScore(entry){const all=loadRanking().filter(e=>e.id!==entry.id).concat(entry);saveRanking(all);const list=loadRanking();const byScore=[...list].sort((a,b)=>b.score-a.score||b.distance-a.distance);const rank=byScore.findIndex(e=>e.id===entry.id)+1;return{rank,list,best:bestScore};}
function formatRunWhen(at){if(!at)return'Earlier';const d=new Date(at),now=new Date();const same=d.toDateString()===now.toDateString();const t=d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});if(same)return`Today ${t}`;const y=new Date(now);y.setDate(y.getDate()-1);if(d.toDateString()===y.toDateString())return`Yesterday ${t}`;return d.toLocaleDateString([],{day:'numeric',month:'short'})+' '+t;}
function renderRankList(el,list,highlightId=null){if(!list.length){el.innerHTML='<li><span>—</span><span>No previous runs yet.</span><strong>0</strong></li>';return;}const best=list.reduce((m,e)=>Math.max(m,e.score||0),0);el.innerHTML=list.map((e,i)=>{const isBest=e.score===best&&best>0;const tag=e.id===highlightId?' (this run)':(isBest?' · best':'');return`<li class="${e.id===highlightId?'you':''}${isBest?' best':''}"><span>#${i+1}</span><span>${formatRunWhen(e.at)}${tag}<em> · Lv ${e.level} · ${e.distance} m${e.wins?` · ${e.wins} KO`:''}</em></span><strong>${e.score}</strong></li>`;}).join('');}
