function scoreVoice(v,want){const n=`${v.name} ${v.voiceURI}`.toLowerCase(),lang=(v.lang||'').toLowerCase();let s=0;if(lang.startsWith(want.lang))s+=12;else if(lang.startsWith(want.lang.slice(0,2)))s+=6;if(/premium|enhanced|neural|natural|online|wavenet|studio|superstar|microsoft.*online|google/.test(n))s+=10;if(/samantha|moira|karen|victoria|zira|jenny|aria|sonia|sara|susan|fiona|ava|emma/.test(n)&&want.gender==='f')s+=8;if(/david|mark|daniel|george|james|brian|guy|ryan|thomas|alex|fred|arthur/.test(n)&&want.gender==='m')s+=8;if(/female|woman/.test(n)&&want.gender==='f')s+=5;if(/male|man/.test(n)&&want.gender==='m')s+=5;if(/compact|eloquence|espeak|dummy/.test(n))s-=8;if(v.localService===false)s+=3;if(want.villain&&(/evil|dark|whisper|raspy/.test(n)||want.gender==='m'))s+=2;return s;}
