function spawnRow(){const L=currentLevel();const lanes=[-1,0,1];const primary=lanes[Math.floor(Math.random()*3)];makeObstacle(pickTrap(L.id),primary,-65);if(Math.random()<L.multi){const other=lanes.filter(l=>l!==primary)[Math.floor(Math.random()*2)];makeObstacle(pickTrap(L.id),other,-65-(Math.random()<.4?0:3.2));}if(Math.random()<L.triple){const last=lanes.find(l=>l!==primary)||0;makeObstacle(pickTrap(L.id),last,-68-Math.random()*4);}}
function run(g,t,power=1,hold=null){g.userData.legs.forEach((o,i)=>o.rotation.x=Math.sin(t*11+i*Math.PI)*.65*power);g.userData.arms?.forEach((o,i)=>{if(hold==='left'&&i===0||hold==='right'&&i===1)return;o.rotation.x=Math.sin(t*11+i*Math.PI)*.6*power;o.rotation.z=0;});}
function holdHands(t){const bob=Math.sin(t*11)*.05,slideScale=slide>0?.45:1;hero.userData.arms[0].rotation.set(.28+bob,.2,-1.05);partner.userData.arms[1].rotation.set(.28+bob,-.2,-1.05);const midX=(hero.position.x+partner.position.x)*.5,midY=Math.max(hero.position.y,partner.position.y)+1.05*slideScale,midZ=(hero.position.z+partner.position.z)*.5;clasped.position.set(midX,midY,midZ);clasped.scale.set(.09*slideScale,.07*slideScale,.09*slideScale);clasped.visible=hero.visible;}
function animateIntro(dt){cinemaTime+=dt;let beat=beats.findLastIndex(b=>cinemaTime>=b.t);if(beat<0)beat=0;if(beat!==lastBeat){lastBeat=beat;$('speaker').textContent=beats[beat].who;$('line').textContent=beats[beat].line;say(beats[beat].line,beats[beat].lang||'en-US',.88,beats[beat].who);$('next-line').textContent=beat>=beats.length-1?'Start chase ▶':'Next ▶';}const t=cinemaTime;if(t<20&&morningTent.visible){morningTent.position.z=.08+Math.sin(t*1.6)*.015;morningTent.rotation.z=.15+Math.sin(t*1.4)*.04;}if(t>6){her.rotation.x=T.MathUtils.lerp(her.rotation.x,-.45,.035);her.userData.head.rotation.y=T.MathUtils.lerp(her.userData.head.rotation.y,-.7,.05);}if(t>13&&t<20){const wiggle=Math.sin(t*18);her.userData.arms[0].rotation.set(.85+wiggle*.2,.35,-1.15+wiggle*.25);morningTent.position.set(0,.72,.08+Math.abs(wiggle)*.05);morningTent.scale.set(1.15+Math.abs(wiggle)*.08,1.15+Math.abs(wiggle)*.08,1.25+Math.abs(wiggle)*.12);morningTent.rotation.z=.15+wiggle*.2;}else if(t<=13||t>=20){her.userData.arms[0].rotation.set(0,0,0);if(t<13)morningTent.scale.set(1.15,1.15,1.25);}if(t>20){him.rotation.x=T.MathUtils.lerp(him.rotation.x,-.45,.035);him.userData.head.rotation.y=T.MathUtils.lerp(him.userData.head.rotation.y,.35,.045);const s=T.MathUtils.lerp(morningTent.scale.x,0,.16);morningTent.scale.setScalar(s);if(s<.05)morningTent.visible=false;}if(t>28){loot.visible=false;stolen.visible=true;luc.position.x=3.7+Math.sin(t*2)*.1;luc.userData.head.rotation.z=Math.sin(t*4)*.08;}if(t>35){luc.position.z+=dt*1.6;run(luc,t);}if(t>=INTRO_END)startGame();}
function animateGame(dt){const L=currentLevel();if(L.id!==levelId){levelId=L.id;toast(`Level ${L.id} — ${L.name} · ${L.theme.name}`);beep(700+L.id*40,.2);applyTheme(L.theme,true);}const speed=L.speed+(distance%LEVEL_LEN)/110+(fleeBoost>0?2.2:0);distance+=speed*dt;score+=speed*dt*(1+L.id*.12)*(runWon?1.15:1);spawn-=dt;if(spawn<=0){spawnRow();spawn=L.spawn*(.8+Math.random()*.35);}jumpV-=dt*21;jump=Math.max(0,jump+jumpV*dt);if(jump===0)jumpV=0;slide=Math.max(0,slide-dt);invincible=Math.max(0,invincible-dt);shake=Math.max(0,shake-dt);knockTime=Math.max(0,knockTime-dt);hitCooldown=Math.max(0,hitCooldown-dt);fleeBoost=Math.max(0,fleeBoost-dt);if(fxTime>0){fxTime-=dt;if(fxTime<=0)$('fx').className='';}hero.visible=invincible<=0||Math.floor(elapsed*12)%2===0;hero.position.x=T.MathUtils.lerp(hero.position.x,lane*2.55,Math.min(1,dt*14));hero.position.y=jump;hero.scale.y=slide>0?.45:1;run(hero,elapsed,1,'left');partner.position.x=T.MathUtils.lerp(partner.position.x,hero.position.x+.85,dt*10);partner.position.y=jump;partner.position.z=T.MathUtils.lerp(partner.position.z,.4,dt*8);partner.scale.y=slide>0?.45:.92;run(partner,elapsed+.3,1,'right');holdHands(elapsed);const striking=canStrike();if(striking&&!strikeArmedToast){strikeArmedToast=true;toast('STRIKE READY — jump / F when he is close!');beep(900,.1);}if(!striking&&(lives<3||leaves<HIT_COST))strikeArmedToast=false;tauntTimer-=dt;if(tauntTimer<=0&&tauntTime<=0&&knockTime<=0){startVillainTaunt();tauntTimer=6.5+Math.random()*5;}if(knockTime>0){runnerCat.rotation.x=T.MathUtils.lerp(runnerCat.rotation.x,1.25,.14);runnerCat.rotation.z=Math.sin(elapsed*18)*.35;runnerCat.position.y=T.MathUtils.lerp(runnerCat.position.y,.05,.12);runnerCat.position.x=T.MathUtils.lerp(runnerCat.position.x,hero.position.x,.12);runnerCat.position.z=T.MathUtils.lerp(runnerCat.position.z,-1.6,.14);chaseJar.rotation.x=-.2;chaseJar.rotation.z=Math.sin(elapsed*12)*.4;}else if(tauntTime>0||striking){if(tauntTime>0)tauntTime-=dt;runnerCat.rotation.x=T.MathUtils.lerp(runnerCat.rotation.x,0,.14);runnerCat.rotation.z=T.MathUtils.lerp(runnerCat.rotation.z,0,.14);runnerCat.rotation.y=T.MathUtils.lerp(runnerCat.rotation.y,0,.16);runnerCat.position.x=T.MathUtils.lerp(runnerCat.position.x,hero.position.x+(striking?0:.25),striking?.14:.07);runnerCat.position.y=.08+Math.abs(Math.sin(elapsed*9))*.16;runnerCat.position.z=T.MathUtils.lerp(runnerCat.position.z,striking?-1.8:(tauntTime>0?-6.5:-16),striking?.16:.07);runnerCat.userData.head.rotation.y=Math.sin(elapsed*7)*.25;runnerCat.userData.head.rotation.z=Math.sin(elapsed*5)*.12;runnerCat.userData.tail.rotation.z=.35+Math.sin(elapsed*10)*.25;run(runnerCat,elapsed,.35);chaseJar.rotation.x=-.7+Math.sin(elapsed*6)*.1;if(tauntTime<=0&&!striking){show('captions',false);runnerCat.userData.head.rotation.y=0;runnerCat.userData.head.rotation.z=0;}}else{runnerCat.rotation.x=T.MathUtils.lerp(runnerCat.rotation.x,0,.1);runnerCat.rotation.z=T.MathUtils.lerp(runnerCat.rotation.z,0,.1);runnerCat.rotation.y=T.MathUtils.lerp(runnerCat.rotation.y,Math.PI,.1);runnerCat.position.x=Math.sin(distance*.075)*2.3;runnerCat.position.y=Math.abs(Math.sin(elapsed*11))*.11;runnerCat.position.z=T.MathUtils.lerp(runnerCat.position.z,fleeBoost>0?-20:-16,.04);run(runnerCat,elapsed);runnerCat.userData.tail.rotation.z=Math.sin(elapsed*6)*.2;chaseJar.rotation.x=-1.05+Math.sin(elapsed*11)*.17;chaseJar.rotation.z=Math.sin(elapsed*8)*.12;}if(striking&&knockTime<=0&&lucNear()&&(jump>.12||slide>.08))landHit();spillTimer-=dt;if(spillTimer<=0){spillLeaf();spillTimer=L.spill[0]+Math.random()*L.spill[1];}
const decorLoop=DECOR_N*DECOR_GAP;for(const g of decor){g.position.z+=speed*dt;if(g.position.z>9)g.position.z-=decorLoop;}
for(let i=obstacles.length-1;i>=0;i--){const o=obstacles[i];const d=o.userData;if(!o.visible&&d.type==='leaf'){obstacles.splice(i,1);continue;}o.position.z+=speed*dt;if(d.roll){o.position.x+=d.vx*dt;o.rotation.z-=d.vx*dt*1.8;if(Math.abs(o.position.x)>2.7)d.vx*=-1;}if(d.spin)o.rotation.y+=dt*4.5;if(d.sway)o.rotation.z=Math.sin(elapsed*5+o.position.z)*.15;if(d.type==='leaf'){d.age+=dt;if(!d.landed){d.vy-=9.8*dt;o.position.y+=d.vy*dt;o.position.x+=d.vx*dt;o.rotation.x+=dt*3.2;o.rotation.z+=dt*d.spin;if(o.position.y<.17){o.position.y=.17;d.landed=true;o.rotation.x=0;o.rotation.z=0;}}else o.rotation.x=Math.sin(d.age*5)*.08;}if(!d.passed&&o.position.z>-.6){d.passed=true;const hitWide=d.wide?Math.abs(hero.position.x-o.position.x)<1.35:Math.abs(hero.position.x-o.position.x)<.95;if(hitWide){if(d.type==='leaf'){if(jump<1.1){leaves++;score+=25+L.id*2;beep(850+leaves%4*100,.07);disposeObj(o);obstacles.splice(i,1);continue;}}else if(invincible===0){if(!avoidedTrap(d.type)){lives--;invincible=1.35;shake=.35;bossHits=0;strikeArmedToast=false;beep(120,.25);toast(lives<3?trapToast(d.type)+' Strikes locked.':trapToast(d.type));triggerFx('pulse');if(lives===0){finish(false);break;}}}}}if(o.position.z>8){disposeObj(o);if(d.type!=='leaf')race.remove(o);obstacles.splice(i,1);}}
updateHud();}
const _camPos=new T.Vector3(),_camTarget=new T.Vector3();
function updateCamera(){const mobile=innerWidth<700||isMobile;if(state==='welcome'){_camPos.set(mobile?10:12,mobile?12:10,mobile?16:17);_camTarget.set(mobile?-.5:-3.7,mobile?3.2:1.2,0);}else if(state==='intro'){const t=cinemaTime;_camPos.set(t<28?(mobile?5.5:7):(mobile?7.5:10),t<28?(mobile?7:8):(mobile?5.5:6),t<28?(mobile?9.5:11):(mobile?8.5:10));_camTarget.set(t<28?0:3.5,t<28?1.1:1,t<28?0:2);}else{_camPos.set(0,mobile?6.2:5.4,mobile?9.2:10.5);_camTarget.set(0,1.05,-8);if(shake>0){_camPos.x+=(Math.random()-.5)*shake*1.2;_camPos.y+=(Math.random()-.5)*shake*.8;}}camera.position.lerp(_camPos,mobile?.1:.07);camera.lookAt(_camTarget);}
function resize(){const w=canvas.clientWidth||innerWidth,h=canvas.clientHeight||innerHeight;renderer.setSize(w,h,false);camera.aspect=w/Math.max(h,1);camera.fov=(innerWidth<700||isMobile)?54:38;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio||1,isMobile?1:1.25));}window.addEventListener('resize',resize);visualViewport?.addEventListener('resize',resize);resize();camera.position.set(12,10,17);
let last=performance.now();function frame(now){const dt=Math.min((now-last)/1000,.05);last=now;if(!paused){elapsed+=dt;if(state==='intro')animateIntro(dt);else if(state==='play')animateGame(dt);else if(state==='welcome'){luc.userData.head.rotation.y=Math.sin(elapsed*.7)*.16;luc.userData.tail.rotation.z=Math.sin(elapsed*2)*.1;}if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0;}}updateCamera();renderer.render(scene,camera);requestAnimationFrame(frame);}requestAnimationFrame(frame);
$('start').onclick=intro;$('direct').onclick=startGame;$('skip').onclick=startGame;$('next-line').onclick=skipDialogue;$('captions').onclick=skipDialogue;$('again').onclick=startGame;$('replay').onclick=intro;$('pause').onclick=togglePause;$('resume').onclick=togglePause;
