$('clear-rank').onclick=()=>{if(confirm('Clear your previous scores on this device?')){localStorage.removeItem(RANK_KEY);localStorage.removeItem('lucjusz-best');bestScore=0;lastRunId=null;renderRankList($('rank-list'),[]);}};
$('sound').onclick=()=>{sound=!sound;$('sound').textContent='Sound: '+(sound?'on':'off');$('sound').setAttribute('aria-pressed',String(sound));if(sound){beep();if(state==='intro'&&lastBeat>=0)say(beats[lastBeat].line,beats[lastBeat].lang||'en-US',.88,beats[lastBeat].who);}else stopVoice();syncMusic();};
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement)return;if(state==='intro'&&(e.key===' '||e.key==='Enter'||e.key==='ArrowRight')){e.preventDefault();skipDialogue();return;}if(e.target instanceof HTMLButtonElement&&(e.key===' '||e.key==='Enter'))return;const map={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'jump',w:'jump',' ':'jump',ArrowDown:'slide',s:'slide',f:'strike',F:'strike'};if(map[e.key]&&state==='play'){e.preventDefault();action(map[e.key]);}if((e.key.toLowerCase()==='p'||e.key==='Escape')&&!victoryOpen)togglePause();});
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();action(b.dataset.action);}));
let touchStart=null;const swipeMin=isMobile?18:25;
canvas.addEventListener('pointerdown',e=>{touchStart=[e.clientX,e.clientY];},{passive:true});
canvas.addEventListener('pointerup',e=>{if(!touchStart||state!=='play'){touchStart=null;return;}const dx=e.clientX-touchStart[0],dy=e.clientY-touchStart[1];if(Math.max(Math.abs(dx),Math.abs(dy))>swipeMin)action(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'slide':'jump');touchStart=null;});
